import { directionOf, type LiteSpec } from './lite';
import type { LiteTiming } from './lite-timing';
import { DEFAULT_SCORE_MIX, EMPTY_BIBLE, normalizeCueSheet, planMovements, type MusicalBible, type ScoreCue, type ScoreDoc, type ScoreMovement } from './score';

/**
 * Film Studio Lite score: one musical identity (theme, palette, key, tempo) shared by every movement, a
 * cue per scene following the story's emotional arc (deliberate silences included), and movements of at
 * most 150 s generated by the studio's music model and crossfaded. Planned from measured timing.
 */

export const LITE_SCORE_ID = 'lite-score';

export function liteMusicalBible(spec: LiteSpec): MusicalBible {
  const d = directionOf(spec.setup.direction);
  const id = spec.sound.music.identity;
  return {
    ...EMPTY_BIBLE,
    mainTheme: id.motif.trim() || `A simple, memorable theme in the spirit of: ${id.style || d.music.style}`,
    emotionalMotif: spec.story.treatment?.tone ? `Carries the film's tone — ${spec.story.treatment.tone}` : '',
    instrumentation: id.instrumentation.filter(Boolean).slice(0, 8),
    key: id.key.trim(),
    tempoRange: { min: Math.min(id.tempo[0], id.tempo[1]), max: Math.max(id.tempo[0], id.tempo[1]) },
    culturalDirection: id.style || d.music.style,
    tensionLanguage: 'held low notes, sparse pulses, unresolved harmony',
    resolutionLanguage: 'the theme returns, warmer and fuller, settling on the tonic',
    avoid: id.avoid.filter(Boolean),
    notes: 'Underscore for a narrated film: leave space for the voice.',
  };
}

/** One cue per scene from the current timing: intensity and direction from the scene, silence where chosen. */
export function liteCueSheet(spec: LiteSpec, timing: LiteTiming): ScoreCue[] {
  const cues = timing.scenes.map((st) => {
    const s = spec.scenes[st.index]!;
    const end = st.index === timing.scenes.length - 1 ? timing.totalSec : st.start + st.duration;
    return {
      id: `cue_${s.id}`,
      sceneId: s.id,
      scene: s.title || `Scene ${st.index + 1}`,
      start: st.blackStart,
      end,
      purpose: [s.purpose, s.music.direction, s.mood].filter((x) => x?.trim()).join(' — ').slice(0, 380),
      intensity: s.music.intensity,
      theme: st.index === 0 ? 'Introduce the main theme gently' : st.index === timing.scenes.length - 1 ? 'Main theme, resolved' : '',
      transitionIn: (st.index === 0 ? 'fade_in' : 'crossfade') as ScoreCue['transitionIn'],
      transitionOut: (st.index === timing.scenes.length - 1 ? 'fade_out' : 'crossfade') as ScoreCue['transitionOut'],
      silence: s.music.mode === 'silence',
      duckForDialogue: Boolean(s.narration.trim()),
      notes: '',
    };
  });
  return normalizeCueSheet(cues, timing.totalSec);
}

/**
 * The score document for the project's `scores` collection. Movements whose scenes are unchanged keep
 * their generated audio (no new request); others are planned afresh.
 */
export function buildLiteScore(spec: LiteSpec, timing: LiteTiming, existing: ScoreDoc | null, title: string): Omit<ScoreDoc, 'id'> {
  const cueSheet = liteCueSheet(spec, timing);
  const planned = planMovements(cueSheet, { crossfadeSec: DEFAULT_SCORE_MIX.crossfadeSec });
  const sig = (m: Pick<ScoreMovement, 'cueIds'>) => m.cueIds.join('|');
  const old = new Map((existing?.movements ?? []).map((m) => [sig(m), m]));
  const movements = planned.map((m) => {
    const prev = old.get(sig(m));
    return prev && prev.assetId ? { ...m, status: prev.status, jobId: prev.jobId, assetId: prev.assetId, durationSec: prev.durationSec, locked: prev.locked, prompt: prev.prompt } : m;
  });
  return {
    title,
    mode: spec.sound.music.mode === 'score' ? 'cinematic' : 'none',
    bible: liteMusicalBible(spec),
    mainThemeLockedAt: existing?.mainThemeLockedAt ?? null,
    bibleApprovedAt: Date.now(),
    cueSheet,
    movements,
    mix: { ...DEFAULT_SCORE_MIX, ducking: false, volumeDb: spec.sound.levels.musicDb },
    importedAssetId: null,
    durationSec: timing.totalSec,
  } as Omit<ScoreDoc, 'id'>;
}

/** Where a planned movement sits now: from the first to the last of its scenes (timing may have moved). */
export function movementSpan(m: Pick<ScoreMovement, 'cueIds' | 'start' | 'end' | 'index'>, timing: LiteTiming, crossfadeSec: number, isFirst: boolean, isLast: boolean): { start: number; end: number } {
  const ids = m.cueIds.map((c) => c.replace(/^cue_/, ''));
  const scenes = timing.scenes.filter((s) => ids.includes(s.sceneId));
  if (!scenes.length) return { start: m.start, end: m.end };
  const start = Math.max(0, scenes[0]!.blackStart - (isFirst ? 0 : crossfadeSec));
  const last = scenes[scenes.length - 1]!;
  const end = isLast || last.index === timing.scenes.length - 1 ? timing.totalSec : last.start + last.duration + crossfadeSec;
  return { start, end };
}
